static const size_t unicode_name_table_count =
    sizeof(unicode_name_table) / sizeof(unicode_name_table[0]);

static inline const char *unicode_name(uint32_t cp) {
    size_t lo = 0, hi = unicode_name_table_count;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        uint32_t mid_cp = unicode_name_table[mid].cp;
        if (cp == mid_cp)
            return unicode_name_table[mid].name;
        else if (cp < mid_cp)
            hi = mid;
        else
            lo = mid + 1;
    }
    return NULL;
}

